-- ============================================================
-- Terex Academy — remplace le cours démo par le parcours principal
-- « Crypto & Blockchain — De zéro à votre premier USDT »
-- 10 modules, ~32 leçons, contenu réel + support Zoom.
-- ============================================================

-- Nettoyer les anciens cours de démo (cascades sur modules/lessons/progress)
DELETE FROM public.courses WHERE slug IN ('crypto-blockchain-fondamentaux', 'crypto-blockchain-parcours');

-- Créer le cours principal
WITH new_course AS (
  INSERT INTO public.courses (title, slug, description, price_cfa, level, duration_hours, status)
  VALUES (
    'Crypto & Blockchain — De zéro à votre premier USDT',
    'crypto-blockchain-parcours',
    'Le parcours complet Terex pour comprendre la crypto sans jargon : de l''histoire de la monnaie à l''achat sécurisé de vos premiers USDT, en passant par la blockchain, les wallets et les bonnes pratiques de sécurité. 10 modules progressifs conçus pour un débutant absolu.',
    30000,
    'debutant',
    8,
    'published'
  )
  RETURNING id
),
-- Module 1
m1 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Bienvenue dans la nouvelle finance', 1 FROM new_course
  RETURNING id
),
m1l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position, is_free_preview)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos, t.preview FROM m1, (VALUES
    (
      'Pourquoi apprendre la crypto en 2026 ?',
      E'La crypto n''est plus une curiosité de geek. En 2026, plus de 500 millions de personnes détiennent au moins un actif numérique dans le monde, et l''Afrique de l''Ouest est l''une des régions qui adopte le plus vite les stablecoins comme l''USDT.\n\nPourquoi ? Parce que la crypto résout des problèmes concrets :\n\n• Envoyer de l''argent à l''étranger en quelques minutes, pour quelques centimes de frais.\n• Se protéger contre l''inflation en détenant un actif stable (USDT est adossé au dollar).\n• Recevoir des paiements internationaux sans passer par une banque.\n• Épargner sur des protocoles qui rapportent 5 à 10% par an.\n\nCe cours est votre point de départ. Vous n''avez besoin d''AUCUN prérequis technique. Nous allons construire votre compréhension brique par brique, avec des exemples concrets tirés du quotidien africain.\n\nÀ la fin du parcours, vous saurez :\n\n• Ce qu''est vraiment une blockchain, en langage simple.\n• La différence entre Bitcoin, Ethereum et les stablecoins.\n• Comment créer et sécuriser votre premier portefeuille.\n• Comment acheter, envoyer et recevoir des USDT en toute sécurité.\n• Comment repérer les arnaques et protéger votre argent.\n\nPrêt ? On y va.',
      3, 1, true
    ),
    (
      'Ce que vous allez maîtriser',
      E'Ce parcours est structuré en 10 modules progressifs. Chaque module s''appuie sur le précédent, alors nous vous conseillons de le suivre dans l''ordre.\n\n**Module 1 — Bienvenue** : le contexte, ce qui vous attend.\n\n**Module 2 — Histoire** : comprendre d''où vient la crypto pour mieux saisir sa force.\n\n**Module 3 — Blockchain** : la technologie derrière, expliquée sans jargon.\n\n**Module 4 — Les grandes cryptos** : Bitcoin, Ethereum, BNB, Solana… qui fait quoi.\n\n**Module 5 — Les stablecoins** : USDT, USDC, et pourquoi ils sont si utiles en Afrique.\n\n**Module 6 — Votre portefeuille** : créer un wallet, sécuriser sa phrase secrète.\n\n**Module 7 — Achat sur Terex** : votre premier achat de USDT, pas à pas.\n\n**Module 8 — Envoyer et recevoir** : maîtriser les réseaux (TRC20, ERC20, BEP20).\n\n**Module 9 — Sécurité** : reconnaître les arnaques, protéger vos comptes.\n\n**Module 10 — Aller plus loin** : DeFi, staking, NFT, et sessions Zoom mensuelles avec un expert Terex.\n\nComptez environ 8 heures au total, en avançant à votre rythme. Chaque leçon fait moins de 10 minutes. Marquez-les comme « terminées » au fur et à mesure — vous verrez votre progression avancer.',
      3, 2, true
    )
  ) AS t(title, body, duration, pos, preview)
  RETURNING 1
),
-- Module 2
m2 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Un peu d''histoire : de l''or à Bitcoin', 2 FROM new_course
  RETURNING id
),
m2l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos FROM m2, (VALUES
    (
      'L''histoire de la monnaie en 10 minutes',
      E'Pour comprendre pourquoi Bitcoin a été inventé, il faut d''abord comprendre ce qu''est une monnaie et comment elle a évolué.\n\n**Le troc (—3000 avant J.-C.)** : on échangeait un mouton contre du blé. Problème : il fallait que les deux personnes veuillent exactement ce que l''autre proposait.\n\n**Les monnaies-marchandises** : coquillages, sel, plumes rares, cauris (utilisés en Afrique de l''Ouest jusqu''au 19e siècle). Un accord collectif sur « ce qui a de la valeur ».\n\n**Les métaux précieux (—600 avant J.-C.)** : l''or et l''argent deviennent la référence. Rares, durables, divisibles. Les premières pièces frappées apparaissent en Lydie (actuelle Turquie).\n\n**Le papier-monnaie (Chine, 7e siècle)** : plus léger, plus pratique. Mais son acceptation dépend de la confiance dans l''émetteur (l''État).\n\n**L''étalon-or (19e siècle — 1971)** : chaque billet était théoriquement échangeable contre une quantité d''or.\n\n**La monnaie fiduciaire (depuis 1971)** : Nixon détache le dollar de l''or. Aujourd''hui, la valeur d''un billet ne repose plus que sur la confiance dans le gouvernement qui l''émet — et sur sa rareté relative.\n\n**Le problème** : les États peuvent imprimer autant de monnaie qu''ils veulent. Résultat : l''inflation grignote le pouvoir d''achat. Un franc CFA de 1990 valait beaucoup plus qu''un franc CFA de 2026.\n\nC''est de ce constat qu''est née une idée : et si on créait une monnaie que personne ne peut imprimer à volonté ?',
      6, 1
    ),
    (
      '2008, la naissance de Bitcoin',
      E'Octobre 2008. Le monde traverse la pire crise financière depuis 1929. La banque Lehman Brothers vient de faire faillite. Des millions de gens perdent leurs économies. Les États impriment des milliards pour sauver les banques.\n\nLe 31 octobre 2008, une personne (ou un groupe) sous le pseudonyme **Satoshi Nakamoto** publie un document de 9 pages : « Bitcoin: A Peer-to-Peer Electronic Cash System ».\n\nL''idée est révolutionnaire : créer une monnaie électronique qui fonctionne **sans banque**, **sans État**, **sans intermédiaire**. Une monnaie dont la quantité totale est fixée à l''avance (21 millions de bitcoins, pas un de plus) et que personne ne peut manipuler.\n\nLe 3 janvier 2009, le premier bloc Bitcoin est créé. Satoshi y inscrit un message :\n\n> « The Times 03/Jan/2009 Chancellor on brink of second bailout for banks »\n\nUne référence à la une du journal britannique The Times ce jour-là — les banques sont à nouveau au bord du gouffre. Un pied-de-nez au système.\n\nJusqu''en 2010, Bitcoin ne valait rien. La première transaction commerciale connue : un développeur a payé 10 000 BTC pour deux pizzas. À l''époque, cela valait 40 dollars. Aujourd''hui, ces 10 000 BTC vaudraient plus d''un milliard de dollars.\n\nEn 2011, Satoshi disparaît définitivement d''internet. Personne ne sait qui il est vraiment. Il aurait environ 1 million de bitcoins — mais n''en a jamais bougé un seul.\n\nBitcoin, lui, ne s''est jamais arrêté. Depuis 15 ans, le réseau fonctionne 24h/24, sans interruption, sans faille.',
      7, 2
    ),
    (
      'La révolution Satoshi',
      E'Ce que Satoshi a inventé va bien au-delà de Bitcoin. Il a résolu un problème mathématique vieux de 30 ans : **comment mettre d''accord un réseau de personnes qui ne se connaissent pas, sans autorité centrale ?**\n\nAvant Bitcoin, tout système numérique de valeur reposait sur un tiers de confiance :\n\n• Votre banque garde le décompte de votre argent.\n• PayPal enregistre vos paiements.\n• Wave sait combien vous avez sur votre compte.\n\nSi ce tiers ferme, disparaît, se fait pirater, ou décide de bloquer votre compte, votre argent est en péril.\n\nSatoshi a proposé une alternative : **la blockchain**. Un grand livre de comptes copié sur des milliers d''ordinateurs à travers le monde, tenu à jour ensemble, sans chef. Si l''un ment, les autres le contredisent.\n\nLes trois innovations majeures :\n\n1. **La preuve de travail (Proof-of-Work)** : pour ajouter une transaction, il faut résoudre un puzzle mathématique coûteux en énergie. Cela empêche de tricher.\n\n2. **La chaîne de blocs cryptographique** : chaque bloc contient l''empreinte du bloc précédent. Modifier un bloc oblige à modifier toute la chaîne — mathématiquement impossible.\n\n3. **La récompense pour les mineurs** : ceux qui sécurisent le réseau reçoivent de nouveaux bitcoins. Un incitatif économique aligné avec la sécurité du système.\n\nAujourd''hui, cette technologie inspire des milliers d''autres projets : Ethereum, Solana, les stablecoins, les NFT, la DeFi. Nous allons les voir dans les modules suivants.',
      6, 3
    )
  ) AS t(title, body, duration, pos)
  RETURNING 1
),
-- Module 3
m3 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Comprendre la blockchain sans jargon', 3 FROM new_course
  RETURNING id
),
m3l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos FROM m3, (VALUES
    (
      'Qu''est-ce qu''une blockchain, vraiment ?',
      E'Imaginez un cahier de comptes de village. Le griot du village y note toutes les transactions : « Ali a donné 3 chèvres à Fatou », « Moussa a payé 500 CFA à Aminata ».\n\nProblème : et si le griot ment ? Et s''il perd le cahier ? Et si quelqu''un déchire une page ?\n\nMaintenant, imaginez que **tout le village** possède une copie identique du cahier. À chaque nouvelle transaction, tout le monde crie ce qui vient de se passer, et chacun l''écrit dans son cahier. Si un tricheur essaie de modifier son cahier, les autres le voient tout de suite : leur version ne correspond plus à la sienne.\n\n**C''est exactement ça, une blockchain.**\n\nÀ l''échelle du monde :\n\n• Le « cahier » = la blockchain.\n• Les « villageois » = les nœuds (ordinateurs) du réseau. Il y en a des dizaines de milliers pour Bitcoin.\n• Les « pages du cahier » = les blocs. Chaque bloc contient des centaines ou milliers de transactions.\n• Le « lien entre deux pages » = une signature cryptographique qui rend impossible de modifier une page sans modifier toutes les suivantes.\n\nRésultat : personne ne peut mentir, personne ne peut effacer, personne ne peut arrêter le réseau. Le cahier est **immuable** et **public**.\n\nC''est cette propriété qui rend la blockchain si puissante — et si différente de tout ce qu''on connaissait avant.',
      6, 1
    ),
    (
      'Un bloc, un mineur, une transaction',
      E'Reprenons notre analogie du village. Voyons ce qui se passe **concrètement** quand vous envoyez 10 USDT à un ami.\n\n**Étape 1 — Vous signez la transaction**\nAvec votre clé privée (le mot de passe secret de votre portefeuille), vous signez : « J''envoie 10 USDT de mon adresse à celle de Fatou ». La signature prouve que c''est bien vous, sans révéler votre mot de passe.\n\n**Étape 2 — La transaction est diffusée sur le réseau**\nElle est envoyée à tous les nœuds du monde en quelques secondes. Chaque nœud vérifie : « Est-ce que cette personne a bien 10 USDT ? Est-ce que sa signature est valide ? »\n\n**Étape 3 — Le mineur regroupe les transactions en un bloc**\nLes mineurs (ou « validateurs » sur certaines blockchains) rassemblent les transactions en attente et forment un bloc. Sur Bitcoin, un nouveau bloc est créé toutes les 10 minutes en moyenne. Sur Tron, c''est toutes les 3 secondes.\n\n**Étape 4 — Le mineur « scelle » le bloc**\nIl résout un puzzle mathématique très coûteux en calcul (c''est ça, la « preuve de travail »). Le premier qui trouve la solution ajoute le bloc à la chaîne et reçoit une récompense en cryptomonnaie.\n\n**Étape 5 — Le bloc est diffusé, tout le monde met à jour**\nTous les nœuds du réseau reçoivent le nouveau bloc, vérifient qu''il est valide, et l''ajoutent à leur copie de la blockchain. Votre transaction est désormais **confirmée et permanente**.\n\nEn tout : entre 3 secondes (Tron) et 60 minutes (Bitcoin) pour qu''une transaction soit totalement sûre.\n\nCe processus est ce qui rend impossible de « dépenser deux fois le même argent » — le fameux problème de la double dépense que Satoshi a résolu.',
      7, 2
    ),
    (
      'Blockchains publiques vs privées',
      E'Toutes les blockchains ne sont pas égales. Il existe plusieurs grandes familles.\n\n**Les blockchains publiques**\nBitcoin, Ethereum, Solana, Tron. Tout le monde peut y participer, y lire les transactions, y devenir validateur. Elles sont ouvertes, censurables par personne. Ce sont celles qui portent l''esprit originel de la crypto.\n\n**Les blockchains privées (ou permissionnées)**\nSouvent utilisées par des entreprises ou des consortiums bancaires. Seuls des acteurs autorisés peuvent y participer. Elles gardent certains bénéfices (traçabilité, automatisation) mais perdent la décentralisation. Exemples : Hyperledger, Corda.\n\n**Les blockchains hybrides**\nElles combinent une couche publique et une couche privée. Utilisées par exemple par des banques centrales pour tester des monnaies numériques (CBDC).\n\n**Pour vous en tant qu''utilisateur crypto**, ce sont uniquement les blockchains publiques qui comptent. Ce sont elles qui hébergent Bitcoin, Ethereum, USDT, et tous les actifs que vous allez manipuler.\n\nParmi les publiques, on distingue deux grandes catégories techniques :\n\n• **Les couches 1 (L1)** : les blockchains de base (Bitcoin, Ethereum, Solana, Tron, BNB Chain). Chacune a son propre système, ses propres validateurs, sa propre monnaie native.\n\n• **Les couches 2 (L2)** : des « surcouches » construites au-dessus d''une L1 pour la rendre plus rapide et moins chère. Exemple : Polygon et Arbitrum sont des L2 d''Ethereum.\n\nQuand vous achetez de l''USDT sur Terex, vous choisirez sur quel réseau vous le recevez : TRC20 (sur Tron), ERC20 (sur Ethereum), BEP20 (sur BNB Chain), etc. On y reviendra en détail au Module 8.',
      6, 3
    )
  ) AS t(title, body, duration, pos)
  RETURNING 1
),
-- Module 4
m4 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Bitcoin, Ethereum & les grandes cryptos', 4 FROM new_course
  RETURNING id
),
m4l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos FROM m4, (VALUES
    (
      'Bitcoin (BTC) — l''or numérique',
      E'Bitcoin est la crypto originelle, la plus ancienne (2009) et de loin la plus valorisée. On l''appelle souvent « l''or numérique » — et pour de bonnes raisons.\n\n**Ses caractéristiques uniques :**\n\n• **Rareté programmée** : il n''y aura jamais plus de 21 millions de BTC. Aucune autorité ne peut en créer davantage. Cette rareté est inscrite dans le code.\n\n• **Émission décroissante (le halving)** : tous les 4 ans environ, la récompense reçue par les mineurs est divisée par deux. Résultat : de moins en moins de bitcoins sont créés chaque année. En 2140, le dernier bitcoin sera miné.\n\n• **Sécurité imbattable** : le réseau Bitcoin est protégé par une quantité d''énergie colossale. L''attaquer coûterait des dizaines de milliards de dollars — et ne rapporterait rien à celui qui essaierait.\n\n• **Simplicité voulue** : Bitcoin ne fait qu''une chose, mais il la fait bien : transférer de la valeur. Il n''y a pas de « smart contracts » complexes. C''est un choix.\n\n**À quoi ça sert concrètement ?**\n\n• Réserve de valeur à long terme : de plus en plus d''entreprises et de particuliers en détiennent comme protection contre l''inflation.\n\n• Envoi international : envoyer 10 000$ à Dubaï en 20 minutes, pour 2$ de frais, sans passer par une banque.\n\n• Actif spéculatif : son prix bouge beaucoup, ce qui attire les traders (mais rend son achat risqué à court terme).\n\n**Attention** : Bitcoin n''est PAS adapté pour les paiements du quotidien. Trop lent, frais qui varient, prix volatil. Pour ça, les stablecoins (Module 5) sont beaucoup mieux.',
      6, 1
    ),
    (
      'Ethereum (ETH) — l''ordinateur mondial',
      E'Si Bitcoin est de l''or numérique, Ethereum est un **ordinateur mondial décentralisé**. Lancé en 2015 par Vitalik Buterin (alors âgé de 21 ans), Ethereum ne se contente pas de transférer de la valeur : il permet d''exécuter des programmes.\n\n**Le concept clé : le smart contract**\n\nUn smart contract est un programme qui s''exécute automatiquement quand une condition est remplie. Exemple : « Si Ali envoie 100 USDT à ce contrat avant le 31 décembre, alors le contrat envoie automatiquement 1 NFT à son adresse ».\n\nUne fois déployé, ce programme :\n\n• Fonctionne sans intermédiaire.\n• Ne peut pas être modifié.\n• Ne peut pas être arrêté (sauf s''il a été programmé pour ça).\n\n**Ce que ça a permis de créer :**\n\n• **Les stablecoins comme USDT** : un smart contract qui garantit qu''un token vaut toujours 1 dollar.\n\n• **Les échanges décentralisés (DEX)** : Uniswap, PancakeSwap. Échanger des cryptos sans passer par une plateforme centralisée.\n\n• **La DeFi** : prêter et emprunter des cryptos à des taux de marché, gagner des intérêts sur ses économies.\n\n• **Les NFT** : preuves d''unicité et de propriété pour l''art numérique, la musique, les jeux vidéo.\n\n• **Les DAO** : organisations gérées collectivement par des règles inscrites sur la blockchain.\n\n**Le point faible historique d''Ethereum** : les frais de transaction peuvent monter très haut quand le réseau est saturé (parfois 20-50$ par transaction). C''est pour ça que d''autres blockchains sont apparues (Solana, Tron, BNB Chain) — pour offrir les mêmes services moins cher.\n\nPour l''USDT, si vous voulez le moins cher : Tron (TRC20). Si vous voulez le plus universel : Ethereum (ERC20).',
      6, 2
    ),
    (
      'BNB, Solana, Tron, Polygon — les autres écosystèmes',
      E'Après Bitcoin et Ethereum, plusieurs blockchains alternatives (parfois appelées « alt-chains ») sont apparues pour offrir des transactions plus rapides et moins chères.\n\n**Tron (TRX)**\nLancée en 2017 par Justin Sun. C''est LA blockchain de choix pour envoyer de l''USDT en Afrique et en Asie du Sud-Est. Pourquoi ? Les frais sont minuscules (~1 USDT par transfert), et c''est très rapide (3 secondes par bloc). Sur Terex, le réseau **TRC20** = Tron.\n\n**BNB Chain (anciennement Binance Smart Chain)**\nLancée en 2020 par la plateforme Binance. Compatible avec Ethereum, mais 50 fois moins chère. Utilisée pour PancakeSwap (le plus gros DEX), pour les jeux crypto, pour de nombreux projets africains. Sur Terex, **BEP20** = BNB Chain.\n\n**Solana (SOL)**\nLancée en 2020. Une des plus rapides du monde : plus de 50 000 transactions par seconde théoriques. Frais quasi nuls (0,0001$). Très populaire pour les NFT et les paiements. Écosystème dynamique mais réseau qui a connu quelques pannes.\n\n**Polygon (MATIC / POL)**\nUne « couche 2 » construite au-dessus d''Ethereum. Elle hérite de la sécurité d''Ethereum mais avec des frais 1000 fois plus bas. Utilisée par Starbucks, Reddit, Nike pour leurs projets NFT.\n\n**Aptos, Sui, TON…**\nLa nouvelle génération. Aptos et Sui sont issus de l''ancien projet Diem de Facebook. TON est né de Telegram. Ils promettent des performances encore supérieures.\n\n**Ce qu''il faut retenir**\n\nPour un utilisateur africain qui veut de l''USDT :\n\n1. **TRC20 (Tron)** = le moins cher, le plus utilisé en Afrique. Notre recommandation par défaut.\n2. **BEP20 (BNB Chain)** = pas cher, utile si vous utilisez Binance.\n3. **ERC20 (Ethereum)** = le plus universel, mais frais plus élevés.\n4. **Polygon, Solana, Aptos** = si votre destinataire vous demande spécifiquement ce réseau.\n\n**Règle d''or absolue** : le réseau d''envoi et le réseau de réception DOIVENT être identiques. Envoyer de l''USDT-TRC20 sur une adresse ERC20 = perte définitive. Nous approfondirons ce point critique au Module 8.',
      7, 3
    )
  ) AS t(title, body, duration, pos)
  RETURNING 1
),
-- Module 5
m5 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Les stablecoins : USDT & pourquoi c''est utile', 5 FROM new_course
  RETURNING id
),
m5l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos FROM m5, (VALUES
    (
      'Qu''est-ce qu''un stablecoin ?',
      E'Un stablecoin est une cryptomonnaie dont le prix est **stable** par construction — parce qu''il est adossé à un actif traditionnel, généralement le dollar américain.\n\n**Le problème que ça résout**\n\nBitcoin peut monter de 20% en une semaine. Ethereum peut chuter de 15% en un jour. Ces variations sont excellentes pour les traders, mais impraticables pour :\n\n• Payer votre loyer en crypto.\n• Recevoir votre salaire en crypto.\n• Épargner sans stress.\n• Faire du commerce international.\n\nOn a besoin d''une crypto **prévisible**. C''est là qu''interviennent les stablecoins.\n\n**Le principe**\n\nUne société (Tether pour l''USDT, Circle pour l''USDC) garde en réserve 1 dollar réel pour chaque token émis. Vous pouvez à tout moment échanger vos tokens contre des dollars auprès de l''émetteur (avec de gros minimums). Cette promesse d''échange garantit que le prix reste très proche de 1$.\n\nÉvidemment, il faut faire confiance à l''émetteur : est-ce qu''il a vraiment les réserves qu''il prétend avoir ? Tether publie des rapports d''audit trimestriels. USDC (émis par Circle, entreprise américaine régulée) est considéré comme encore plus transparent.\n\n**Les grandes catégories**\n\n1. **Stablecoins collatéralisés en fiat** : USDT, USDC. 1 token = 1 dollar en réserve. Les plus utilisés (>200 milliards en circulation).\n\n2. **Stablecoins collatéralisés en crypto** : DAI. Adossés à d''autres cryptos comme collatéral. Plus décentralisés, plus complexes.\n\n3. **Stablecoins algorithmiques** : ils tentent de maintenir leur prix par des mécanismes de marché. L''expérience Terra/UST en 2022 a montré leur fragilité — évitez-les.\n\nPour vous, en Afrique de l''Ouest, **retenez : USDT et USDC**. Ce sont les deux références.',
      6, 1
    ),
    (
      'USDT — le pilier de l''échange',
      E'USDT (Tether) est le stablecoin le plus utilisé au monde. Lancé en 2014, il représente aujourd''hui plus de 60% du marché des stablecoins, avec une capitalisation de plus de 200 milliards de dollars.\n\n**Pourquoi USDT est-il devenu la référence en Afrique ?**\n\n1. **Il est partout** : accepté sur toutes les plateformes d''échange, tous les portefeuilles, tous les marchands crypto africains.\n\n2. **Il est stable** : 1 USDT ≈ 1 USD, à quelques dixièmes de cent près.\n\n3. **Il protège contre l''inflation locale** : le franc CFA est stable, mais dans d''autres pays africains (Nigeria, Ghana, Zimbabwe), les monnaies locales perdent 10 à 50% par an. Détenir des USDT = détenir des dollars sans compte bancaire américain.\n\n4. **Il traverse les frontières** : envoyer 500 USDT du Sénégal au Cameroun prend 10 minutes et coûte moins de 1$. Impossible avec un virement bancaire classique.\n\n5. **Il est disponible sur plusieurs réseaux** : Tron, Ethereum, BNB Chain, Solana, Polygon. Vous choisissez selon votre besoin.\n\n**Les cas d''usage concrets en Afrique**\n\n• **Épargner en dollars sans banque** : impossible d''ouvrir un compte USD au Sénégal ? Achetez des USDT sur Terex.\n\n• **Payer un fournisseur en Chine** : plus rapide et moins cher qu''un virement bancaire.\n\n• **Envoyer de l''argent à la famille à l''étranger** : votre neveu en France reçoit ses USDT en 10 minutes.\n\n• **Recevoir un paiement d''un client international** : freelance, e-commerce, consultant — vous êtes payé sans commission bancaire de 3-5%.\n\n• **Faire du trading** : USDT est la paire de référence face à toutes les autres cryptos sur les plateformes.\n\n**Est-ce que USDT est risqué ?**\n\nLe risque principal est un défaut de Tether (la société qui l''émet). C''est théoriquement possible, mais c''est aujourd''hui le stablecoin le plus liquide et l''un des plus scrutés du secteur. Pour limiter le risque, ne stockez pas des centaines de milliers de dollars sur un seul stablecoin — diversifiez avec USDC si les montants sont importants.',
      7, 2
    ),
    (
      'TRC20, ERC20, BEP20 — comment choisir ?',
      E'C''est LA question que se pose tout débutant à son premier achat de USDT. Explication simple.\n\nUn USDT est un token — un jeton numérique. Ce jeton peut « voyager » sur plusieurs blockchains différentes. On appelle ça un token multi-chaîne.\n\nQuand vous achetez de l''USDT sur Terex, vous devez choisir **sur quel réseau** vous voulez le recevoir. Le token sera alors émis sur ce réseau spécifique, et vous devrez donner une adresse compatible avec ce réseau.\n\n**Comparaison rapide :**\n\n**TRC20 (réseau Tron)**\n• Frais : ~1 USDT par transfert\n• Vitesse : 3 secondes\n• Le + utilisé en Afrique\n• Le + recommandé par Terex pour la plupart des cas\n• Adresse : commence par « T »\n\n**BEP20 (réseau BNB Chain)**\n• Frais : ~0,20 USDT par transfert\n• Vitesse : 3 secondes\n• Très utilisé si vous avez un compte Binance\n• Écosystème DeFi très riche\n• Adresse : commence par « 0x »\n\n**ERC20 (réseau Ethereum)**\n• Frais : 3 à 30 USDT selon la congestion (attention !)\n• Vitesse : 15 secondes à quelques minutes\n• Le réseau le plus « universel », toujours accepté\n• Recommandé uniquement pour de gros montants (>500$) où les frais deviennent relativement faibles\n• Adresse : commence par « 0x »\n\n**Polygon, Solana, Aptos**\n• Frais quasi nuls\n• Utile si votre destinataire vous demande ce réseau spécifiquement\n\n**Comment choisir ?**\n\n1. Demandez à votre destinataire quel réseau il préfère. Il faut absolument que vous envoyiez sur le même réseau que celui de son adresse.\n\n2. Si vous choisissez pour vous-même, prenez **TRC20** par défaut. C''est le standard en Afrique.\n\n3. Vérifiez toujours que votre wallet (Trust Wallet, MetaMask, Binance…) supporte le réseau choisi. Certains wallets ne gèrent que Ethereum et BNB Chain, pas Tron.\n\n**AVERTISSEMENT CRITIQUE**\n\nSi vous envoyez de l''USDT-TRC20 à une adresse ERC20 (ou l''inverse), **votre argent est perdu à jamais**. Ces réseaux sont incompatibles. C''est l''erreur numéro 1 des débutants. On y reviendra en détail au Module 8.\n\nSur Terex, l''interface vous demande de choisir le réseau AVANT de renseigner l''adresse — c''est fait exprès pour vous éviter cette erreur.',
      7, 3
    )
  ) AS t(title, body, duration, pos)
  RETURNING 1
),
-- Module 6
m6 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Créer et sécuriser son portefeuille', 6 FROM new_course
  RETURNING id
),
m6l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos FROM m6, (VALUES
    (
      'Custodial vs non-custodial : la différence essentielle',
      E'Avant de créer votre wallet, vous devez comprendre une distinction fondamentale : **qui détient vraiment vos cryptos ?**\n\n**Le wallet custodial (garde partagée)**\n\nUn tiers (une plateforme comme Binance, Coinbase) garde vos cryptos pour vous. Vous avez un compte et un mot de passe, comme sur une application bancaire.\n\nAvantages :\n• Simple à utiliser\n• Récupération de compte possible (mot de passe oublié = pas de panique)\n• Support client\n\nInconvénients :\n• Vous ne contrôlez pas vraiment vos fonds\n• Si la plateforme fait faillite (comme FTX en 2022), vos fonds sont bloqués voire perdus\n• La plateforme peut geler votre compte à tout moment\n• Piratage massif possible (Mt. Gox en 2014, plus récemment en 2024)\n\n**Le wallet non-custodial (contrôle total)**\n\nVous êtes seul détenteur. Une phrase secrète de 12 ou 24 mots vous donne un contrôle exclusif. Personne d''autre au monde n''y a accès — pas même le créateur du wallet.\n\nExemples : Trust Wallet, MetaMask, Phantom, Rabby, Ledger.\n\nAvantages :\n• Vous êtes maître de vos cryptos\n• Aucun tiers ne peut geler ou perdre vos fonds\n• Vous pouvez interagir avec toute l''écosystème crypto (DEX, DeFi, NFT)\n\nInconvénients :\n• Si vous perdez votre phrase secrète, votre argent est PERDU. Personne ne peut la récupérer.\n• Aucun support client — vous êtes responsable\n• Il faut apprendre les bonnes pratiques de sécurité (voir leçons suivantes)\n\n**Le proverbe crypto** : *« Not your keys, not your coins »* — Si vous n''avez pas les clés, ce ne sont pas vos cryptos.\n\n**Recommandation Terex**\n\nPour les petits montants (< 500$), un wallet custodial comme Binance suffit pour commencer.\n\nDès que vous avez des sommes significatives, ou dès que vous voulez vraiment être autonome, passez à un wallet non-custodial. Trust Wallet (édité par Binance) est excellent pour débuter — nous en montrons la création à la leçon suivante.',
      6, 1
    ),
    (
      'Créer un wallet Trust Wallet — pas à pas',
      E'Trust Wallet est le portefeuille non-custodial le plus populaire au monde (>60 millions d''utilisateurs). Il supporte tous les grands réseaux (Tron, Ethereum, BNB Chain, Solana, Polygon…). Gratuit, open-source, disponible sur mobile.\n\n**Étape 1 — Télécharger l''application**\n\nAllez sur trustwallet.com et téléchargez l''app :\n• iPhone : App Store\n• Android : Google Play\n\n**⚠️ ATTENTION** : ne téléchargez JAMAIS depuis un lien qu''on vous envoie sur WhatsApp ou Telegram. Toujours depuis les stores officiels. Il existe des fausses versions qui volent votre phrase secrète.\n\n**Étape 2 — Ouvrir un nouveau wallet**\n\nÀ l''ouverture, choisissez « Créer un nouveau portefeuille » (pas « Importer un portefeuille » — ça, c''est si vous avez déjà une phrase secrète).\n\nAcceptez les conditions.\n\n**Étape 3 — Notez votre phrase secrète (LE MOMENT CRITIQUE)**\n\nL''application va vous afficher 12 mots dans un ordre précis. Par exemple :\n\n1. voyage    2. table    3. lampe    4. écrire\n5. cheval    6. lundi    7. simple   8. mardi\n9. arbre    10. porte   11. clef    12. terre\n\n**Ces 12 mots SONT votre wallet.**\n\n• Quiconque possède ces 12 mots peut vider votre wallet en 30 secondes.\n• Si vous les perdez, vous perdez tout — définitivement, sans recours.\n\n**Comment les stocker** :\n\n✅ Écrivez-les à la main sur un papier. Deux copies, dans deux endroits différents.\n✅ Envisagez une plaque en métal (indestructible, résiste au feu et à l''eau) pour les gros montants.\n✅ Vérifiez que vous les avez bien écrits : l''app vous demandera de re-taper les mots dans l''ordre.\n\n❌ NE prenez PAS de photo avec votre téléphone.\n❌ NE la stockez PAS dans Google Drive, iCloud, Dropbox, Notes.\n❌ NE l''envoyez à PERSONNE — pas même par WhatsApp à vous-même.\n❌ NE la tapez PAS dans un formulaire en ligne.\n\n**Étape 4 — Vérifier**\n\nL''app vous demande de retaper vos 12 mots dans l''ordre. C''est un test pour s''assurer que vous les avez bien notés.\n\n**Étape 5 — Ajouter les tokens que vous voulez suivre**\n\nDans l''app, appuyez sur l''icône ⚙️ ou « Gérer les cryptos ». Activez :\n• USDT sur Tron (TRC20)\n• USDT sur BNB Chain (BEP20)\n\nVotre wallet est prêt à recevoir des USDT. Copiez votre adresse Tron (elle commence par « T ») — c''est cette adresse que vous donnerez à Terex lors de votre achat.',
      8, 2
    ),
    (
      'La phrase secrète : la règle d''or',
      E'Si vous ne retenez qu''UNE seule chose de tout ce cours, c''est celle-ci : **votre phrase secrète (seed phrase) doit rester secrète, physique, hors ligne.**\n\n**Pourquoi c''est si important ?**\n\nVotre phrase secrète n''est pas un mot de passe. Un mot de passe peut être réinitialisé. Votre phrase secrète, elle, EST votre wallet. Elle a été générée aléatoirement parmi 2¹²⁸ possibilités — plus grand que le nombre d''atomes dans l''univers observable.\n\nAvec cette phrase :\n\n• N''importe qui peut recréer votre wallet sur n''importe quel appareil, n''importe où dans le monde.\n• L''accès est instantané, irréversible, invisible.\n• Vous ne recevrez AUCUNE alerte.\n\n**Les erreurs qui coûtent une fortune**\n\n1. **La stocker en ligne** : Google Drive piraté = fonds volés. Cas ultra fréquent.\n\n2. **Prendre une photo** : votre téléphone est piraté ou perdu = fin de partie.\n\n3. **La saisir sur un site** : AUCUN site légitime ne vous demandera jamais votre phrase secrète. AUCUN. Si un site vous la demande = c''est une arnaque, à 100%.\n\n4. **La donner à un « support technique »** : Trust Wallet et MetaMask N''ONT PAS de support qui vous contactera. Si quelqu''un se dit « support » et vous demande votre phrase = arnaque.\n\n5. **La partager avec un « conseiller » sur Telegram/WhatsApp** : les groupes crypto sont infestés d''arnaqueurs. Ne donnez JAMAIS votre phrase à personne.\n\n**Les bonnes pratiques concrètes**\n\n• **Papier** : deux copies écrites à la main, deux endroits distincts (par exemple : votre maison + celle d''un parent de confiance dans une enveloppe cachetée).\n\n• **Métal** : pour les montants importants (>5000$), une plaque gravée en acier inoxydable (Cryptosteel, Billfodl) protège du feu, de l''eau, du temps.\n\n• **Séparez si possible** : certains coupent leur phrase en deux, chaque moitié dans un endroit différent (attention à la logistique).\n\n• **Faites un test** : dès la création, essayez de restaurer votre wallet sur un autre téléphone à partir de la phrase. Confirmez que vous accédez bien à votre solde. Puis effacez cette instance test.\n\n**Rappel final**\n\nEn crypto, vous êtes votre propre banque. Cela veut dire :\n\n• Une liberté totale.\n• Une responsabilité totale.\n• Aucun recours possible en cas d''erreur.\n\nProtégez votre phrase comme si votre patrimoine en dépendait — parce que c''est le cas.',
      6, 3
    )
  ) AS t(title, body, duration, pos)
  RETURNING 1
),
-- Module 7 — Acheter sur Terex
m7 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Acheter son premier USDT sur Terex', 7 FROM new_course
  RETURNING id
),
m7l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos FROM m7, (VALUES
    (
      'Comment Terex fonctionne',
      E'Terex est une plateforme d''échange peer-to-peer entre le franc CFA (via mobile money) et l''USDT. Notre mission : rendre l''achat de crypto simple, rapide et sécurisé pour les Africains de l''Ouest.\n\n**Ce que vous pouvez faire sur Terex**\n\n• **Acheter des USDT** en payant en franc CFA via Wave ou Orange Money.\n• **Vendre des USDT** et recevoir vos francs CFA sur Wave ou Orange Money.\n• **Choisir votre réseau** : TRC20, BEP20, ERC20, Polygon, Solana, Aptos.\n• **Suivre vos transactions** dans un historique clair et transparent.\n\n**Comment nous fonctionnons**\n\nContrairement aux grosses plateformes internationales, Terex ne détient PAS vos cryptos. C''est ce qu''on appelle un modèle « non-custodial » : vous nous envoyez du CFA, on vous envoie directement des USDT sur VOTRE wallet.\n\nCela veut dire :\n\n• Vous devez avoir un wallet à vous (voir Module 6).\n• Vos USDT arrivent chez vous, pas dans un compte Terex.\n• Il n''y a rien à retirer, rien à débloquer — vous êtes maître de vos fonds dès la fin de la transaction.\n\n**Le processus type d''un achat**\n\n1. Vous entrez le montant en CFA (ex : 60 000 CFA).\n2. Le système calcule le nombre de USDT que vous allez recevoir au taux du jour.\n3. Vous choisissez le réseau (TRC20 recommandé).\n4. Vous renseignez l''adresse de votre wallet.\n5. Vous payez via Wave ou Orange Money.\n6. Nous validons le paiement et envoyons les USDT.\n7. Vous les recevez dans votre wallet en quelques secondes à quelques minutes.\n\n**Nos frais**\n\nAucun frais caché. Le taux affiché est le taux que vous obtenez. Nous prenons une petite marge sur le taux de change (généralement 2 à 3%), c''est tout.\n\n**Notre équipe**\n\nNous sommes une équipe basée en Afrique de l''Ouest. Notre support est disponible 24h/24 par chat et WhatsApp. Toute question, toute inquiétude, contactez-nous — c''est un vrai humain qui vous répond.\n\nLes leçons suivantes détaillent chaque étape de votre premier achat.',
      5, 1
    ),
    (
      'Étape 1 — Choisir le montant et le réseau',
      E'Rendez-vous sur l''onglet « Acheter » depuis votre tableau de bord Terex. La page s''ouvre sur l''écran principal.\n\n**Entrer le montant**\n\nDeux façons de saisir :\n\n• **En CFA** : « Je veux acheter pour 60 000 CFA de USDT ». Vous voyez alors combien de USDT vous allez recevoir.\n\n• **En USDT** : « Je veux exactement 100 USDT ». Vous voyez alors combien de CFA vous devez payer.\n\nLe minimum est de **20 000 CFA** par transaction. Pas de maximum sauf grosse limite mensuelle (nous contacter pour les gros volumes).\n\nLe taux affiché est le taux **du jour**, mis à jour toutes les 30 secondes. Il est fixe pendant votre transaction : une fois que vous cliquez sur « Continuer », le taux est verrouillé pendant 15 minutes.\n\n**Choisir le réseau**\n\nSix réseaux sont disponibles sur Terex :\n\n• **Tron (TRC20)** — recommandé par défaut. Le moins cher, le plus rapide, le plus utilisé en Afrique.\n\n• **BNB Chain (BEP20)** — utile si vous utilisez Binance ou PancakeSwap.\n\n• **Ethereum (ERC20)** — universel mais frais élevés. Choisissez-le si votre destinataire l''exige.\n\n• **Polygon** — quasi gratuit, écosystème NFT et jeux.\n\n• **Solana** — ultra rapide, quasi gratuit, très utilisé pour les paiements.\n\n• **Aptos** — nouvelle génération, si votre wallet le supporte.\n\n**Comment choisir ?**\n\nPosez-vous une seule question : **quel wallet ai-je créé et quel réseau utilise-t-il ?**\n\n• Trust Wallet, MetaMask, Binance → tous supportent TRC20 et BEP20. Prenez TRC20 pour économiser sur les frais.\n\n• Phantom → Solana uniquement.\n\n• Un wallet particulier ? Vérifiez la doc ou demandez à notre support.\n\nUne fois le réseau choisi, cliquez sur « Continuer ». Vous passez à l''étape 2.',
      5, 2
    ),
    (
      'Étape 2 — Renseigner votre adresse',
      E'C''est l''étape la plus critique de tout le processus. Nous allons envoyer vos USDT à l''adresse que vous saisissez ici — donc **une erreur = fonds perdus**.\n\n**Comment récupérer votre adresse**\n\nDans votre wallet (Trust Wallet, MetaMask, Binance, etc.) :\n\n1. Cherchez l''USDT sur le réseau choisi (ex : « USDT (TRC20) »).\n2. Cliquez sur « Recevoir » ou « Deposit ».\n3. Votre adresse s''affiche. Elle ressemble à :\n\n**Format TRC20 (Tron)** : `TN2G8...` (commence par T, 34 caractères).\n\n**Format ERC20 / BEP20** : `0xAb3F...` (commence par 0x, 42 caractères).\n\n**Format Solana** : `9WzD...` (Base58, 32-44 caractères).\n\n4. Copiez cette adresse.\n\n**Coller dans Terex**\n\nRevenez sur Terex et collez l''adresse dans le champ prévu. La plateforme vérifie automatiquement que le format correspond au réseau choisi. Si vous vous êtes trompé, un message rouge apparaît.\n\n**Les bonnes pratiques**\n\n✅ **Copier-coller, jamais taper à la main** : les adresses sont longues et complexes. Une seule lettre différente = fonds perdus.\n\n✅ **Vérifier les 4 premiers et les 4 derniers caractères** : après avoir collé, comparez visuellement avec votre wallet. Certains virus (« clipboard hijackers ») remplacent votre adresse copiée par celle d''un pirate — vérifier détecte l''attaque.\n\n✅ **Faire un premier test avec un petit montant** : pour votre tout premier achat, n''hésitez pas à faire 20 000 CFA. Une fois que vos USDT arrivent bien, vous pouvez continuer sereinement avec de plus gros montants.\n\n✅ **Utiliser la fonction QR code** : si vous êtes en face de votre wallet, scannez le QR code plutôt que de copier-coller. Zéro erreur possible.\n\n**Enregistrer votre adresse dans Terex**\n\nSi vous cochez « Enregistrer cette adresse », Terex la mémorise pour vos prochains achats. Vous n''aurez plus qu''à la sélectionner dans une liste. Pratique et sûr (l''adresse est stockée chiffrée dans votre compte).\n\nUne fois l''adresse validée, cliquez sur « Continuer ». Vous passez au paiement.',
      6, 3
    ),
    (
      'Étape 3 — Payer via Wave ou Orange Money',
      E'À cette étape, Terex vous génère un lien de paiement Wave ou un numéro Orange Money spécifique à votre transaction.\n\n**Si vous payez par Wave**\n\n1. Un bouton « Payer avec Wave » apparaît. Cliquez dessus.\n2. Vous êtes redirigé vers l''app Wave (ou vers un lien QR à scanner).\n3. Le montant et le destinataire sont pré-remplis — vous n''avez rien à modifier.\n4. Validez le paiement dans Wave avec votre PIN.\n\n**Si vous payez par Orange Money**\n\n1. Terex vous affiche un numéro Orange Money et le montant exact.\n2. Composez `#144#` sur votre téléphone.\n3. Envoyez ce montant EXACT au numéro affiché.\n4. Notez la référence de la transaction OM que vous recevez par SMS.\n5. Collez cette référence dans le champ Terex prévu à cet effet.\n\n**Règles importantes**\n\n⚠️ **Envoyez le montant EXACT** affiché par Terex, au centime près. Un montant différent bloque la validation automatique et nécessite une intervention manuelle de notre équipe (délai supplémentaire).\n\n⚠️ **N''ajoutez PAS de message personnel** dans le champ « description » de Wave ou OM. Laissez celui que Terex a préparé — il contient votre référence de transaction.\n\n⚠️ **Ne fermez PAS la page Terex** avant confirmation du paiement. Vous pouvez la mettre en arrière-plan, mais gardez-la ouverte.\n\n**Ce qui se passe ensuite**\n\nDès que nous recevons votre paiement :\n\n1. Notre système détecte automatiquement la transaction (généralement en 10-30 secondes).\n2. Le statut passe de « En attente de paiement » à « Paiement reçu, envoi des USDT en cours ».\n3. Nous envoyons vos USDT à votre adresse depuis notre pool de liquidités.\n\n**Combien de temps ?**\n\n• Détection du paiement : 10-30 secondes.\n• Envoi et confirmation on-chain :\n  - TRC20 : ~3 secondes\n  - BEP20 : ~3 secondes\n  - Solana : instantané\n  - ERC20 : 15 secondes à quelques minutes selon la congestion\n\nEn moyenne : **moins de 2 minutes** entre votre paiement et l''arrivée des USDT dans votre wallet.\n\n**Si ça met plus de 5 minutes**\n\nPas de panique. Contactez notre support via le chat en bas à droite de votre écran, ou WhatsApp. Nous vérifions en direct l''état de votre transaction et vous répondons en quelques minutes.',
      6, 4
    ),
    (
      'Étape 4 — Recevoir vos USDT',
      E'Ça y est, vos USDT arrivent. Voici ce qui se passe dans votre wallet.\n\n**La notification**\n\nSi votre wallet (Trust Wallet, MetaMask, Binance) a les notifications activées, vous recevez une alerte push : « Vous avez reçu 100 USDT ».\n\nDans l''app :\n\n1. Ouvrez votre wallet.\n2. Sélectionnez USDT sur le réseau utilisé (TRC20 par exemple).\n3. Le solde est mis à jour.\n4. Dans l''historique, la transaction apparaît avec la mention « Received » ou « Received from external ».\n\n**Vérifier la transaction sur la blockchain**\n\nToute transaction blockchain est publique. Vous pouvez la vérifier vous-même sur un « explorateur » :\n\n• Pour TRC20 : allez sur `tronscan.org`, collez votre adresse. Vous voyez toutes vos transactions.\n\n• Pour BEP20 : `bscscan.com`.\n\n• Pour ERC20 : `etherscan.io`.\n\n• Pour Solana : `solscan.io`.\n\nSur Terex, dans votre historique de commande, un bouton « Voir sur la blockchain » vous emmène directement à votre transaction sur le bon explorateur. Transparence totale.\n\n**Combien de confirmations attendre ?**\n\nEn crypto, une transaction est d''abord « en attente » (0 confirmation), puis « confirmée » (1+ confirmations). Plus il y a de confirmations, plus la transaction est immuable.\n\n• Pour TRC20 : 20 confirmations = définitif. C''est atteint en ~1 minute.\n• Pour BEP20 : 15 confirmations = définitif. C''est atteint en ~45 secondes.\n• Pour ERC20 : 12 confirmations = définitif. C''est atteint en ~3 minutes.\n\nDès la première confirmation, vos USDT sont utilisables (vous pouvez les envoyer, les stocker, les convertir). Les confirmations suivantes ne sont importantes que pour de très gros montants.\n\n**Que faire de vos premiers USDT ?**\n\n• **Les garder en épargne** : dans votre wallet, ils gardent leur valeur en dollars.\n\n• **Les envoyer à quelqu''un** : vous pouvez envoyer une partie à un proche à l''étranger. Voir Module 8.\n\n• **Les revendre plus tard** : quand vous voudrez récupérer du CFA, revenez sur Terex → onglet « Vendre ». Le processus est le miroir de l''achat.\n\n• **Les faire fructifier** : sur certaines plateformes DeFi, on peut prêter ses USDT et gagner 5-10% par an. On en parle au Module 10.\n\n**Félicitations**\n\nVous venez de faire votre premier achat crypto. Bienvenue dans l''écosystème.',
      5, 5
    )
  ) AS t(title, body, duration, pos)
  RETURNING 1
),
-- Module 8 — Envoyer / recevoir
m8 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Envoyer, recevoir & comprendre les réseaux', 8 FROM new_course
  RETURNING id
),
m8l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos FROM m8, (VALUES
    (
      'Envoyer des cryptos, pas à pas',
      E'Envoyer des cryptos à quelqu''un fonctionne exactement comme envoyer un e-mail : vous avez une adresse d''envoi (la vôtre), une adresse de réception (celle du destinataire), un montant, et un timbre (les frais réseau).\n\n**Étape 1 — Récupérer l''adresse du destinataire**\n\nDemandez à la personne à qui vous voulez envoyer :\n\n• Son adresse crypto (elle vous la copie-colle).\n• **Le réseau** correspondant. Sans cette info, vous ne pouvez pas envoyer en sécurité.\n\nSi la personne vous envoie une adresse ERC20 mais que vous avez des USDT-TRC20, il faudra soit :\n\n• Lui demander une adresse TRC20.\n• Convertir vos USDT-TRC20 en USDT-ERC20 (via Binance ou un service de bridge — sujet avancé).\n\n**Étape 2 — Ouvrir votre wallet et choisir « Envoyer »**\n\nSélectionnez le token à envoyer (USDT), sur le bon réseau (TRC20 par exemple). Cliquez sur « Envoyer » (ou « Send »).\n\n**Étape 3 — Coller l''adresse**\n\nCopier-coller uniquement. Vérifiez visuellement les premiers et derniers caractères. Si vous êtes en face du destinataire, préférez le QR code.\n\n**Étape 4 — Entrer le montant**\n\nVous pouvez entrer un montant en USDT (« Envoyer 50 USDT ») ou parfois en USD si votre wallet l''affiche.\n\n**Étape 5 — Vérifier les frais réseau**\n\nLe wallet affiche les frais qui seront prélevés. Sur TRC20 : ~1 USDT. Sur ERC20 : peut monter à plusieurs dollars. Les frais sont payés en :\n\n• TRX si vous envoyez depuis Tron.\n• BNB si vous envoyez depuis BNB Chain.\n• ETH si vous envoyez depuis Ethereum.\n• MATIC (ou POL) sur Polygon.\n\n**Important** : vous devez avoir un peu de la monnaie native pour payer les frais. Si vous n''avez que des USDT-TRC20 sans TRX du tout, la transaction échouera. Astuce : gardez toujours l''équivalent de 5$ de monnaie native dans le wallet pour couvrir 5-10 transactions.\n\n**Étape 6 — Confirmer**\n\nUne fois validé, la transaction est diffusée sur le réseau. Vous voyez un ID de transaction (« Transaction Hash »). Gardez-le : il prouve l''envoi et permet de suivre l''état sur l''explorateur.\n\nLe destinataire reçoit ses fonds en quelques secondes à quelques minutes.\n\n**Erreur classique à éviter**\n\nEnvoyer sur le mauvais réseau (TRC20 sur adresse ERC20 par exemple). C''est **la** cause n°1 de perte de fonds. Voir la leçon suivante.',
      6, 1
    ),
    (
      'Comprendre les frais de réseau (gas fees)',
      E'Chaque fois que vous envoyez une transaction sur une blockchain, vous payez des « frais réseau » (ou « gas fees »). C''est ce qui incite les validateurs à traiter votre transaction et sécurise le système.\n\n**D''où viennent ces frais ?**\n\nQuand vous envoyez une transaction, elle rejoint une file d''attente (la « mempool »). Les validateurs choisissent quelles transactions inclure en priorité dans le prochain bloc. Ils choisissent celles qui paient le plus de frais.\n\nDonc : plus vous payez, plus vous êtes servi vite. Moins vous payez, plus votre transaction attend (voire n''est jamais incluse si le prix est trop bas).\n\n**Combien ça coûte ?**\n\n**Tron (TRC20)** : ~1 USDT quel que soit le montant. Ultra prévisible. C''est la raison principale pour laquelle l''USDT-TRC20 domine en Afrique.\n\n**BNB Chain (BEP20)** : ~0,10 à 0,50 USDT. Très raisonnable.\n\n**Polygon** : moins de 0,01 USDT. Quasi gratuit.\n\n**Solana** : 0,00025 SOL ≈ 0,04 USDT. Presque gratuit.\n\n**Ethereum (ERC20)** : très variable. En période calme : 2-5 USDT. En période chargée : 20-50 USDT. En pic de spéculation : jusqu''à 200 USDT pour une simple transaction.\n\nC''est pour ça qu''ERC20 ne devrait être utilisé que pour de gros montants, où les frais deviennent relativement faibles (5% de frais sur 100$ = beaucoup, 5% de frais sur 10 000$ = négligeable).\n\n**Comment ne pas payer trop cher ?**\n\n1. **Choisir le bon réseau** : préférez TRC20 pour les petits transferts USDT.\n\n2. **Éviter les heures de pointe sur Ethereum** : les frais explosent en journée US (14h-23h UTC). Envoyez plutôt le matin ou la nuit.\n\n3. **Regrouper vos envois** : plutôt que d''envoyer 10 fois 10$ à la même personne, envoyez 100$ d''un coup. Frais divisés par 10.\n\n4. **Ne pas paniquer sur une transaction lente** : quand le réseau est chargé, il vaut mieux attendre que d''essayer de « pousser » avec plus de frais. Une transaction peut mettre 30 minutes avant d''être confirmée sans que ce soit un problème.\n\n**Pourquoi les frais existent-ils ?**\n\nSans frais, un attaquant pourrait spammer le réseau avec des millions de transactions vides et le paralyser. Les frais découragent le spam et rétribuent les validateurs. C''est une composante essentielle de la sécurité et de la fluidité du réseau.',
      6, 2
    ),
    (
      'Éviter les erreurs de réseau — la règle absolue',
      E'C''est la leçon la plus importante de tout ce cours. Retenez-la, gravez-la, tatouez-la si nécessaire :\n\n> **Le réseau d''envoi et le réseau de réception DOIVENT être identiques.**\n\nSi vous envoyez de l''USDT sur un réseau incompatible avec l''adresse de destination, vos fonds sont **perdus définitivement**. Personne — pas Terex, pas Trust Wallet, pas Binance — ne peut les récupérer.\n\n**Les erreurs qui arrivent tous les jours**\n\n**Erreur 1 : USDT-TRC20 envoyé à une adresse ERC20 (0x…)**\n\nLes adresses ERC20 et TRC20 ont des formats très différents (0x… vs T…), mais parfois les gens confondent quand même. Une adresse 0x est une adresse Ethereum ou BNB ou Polygon — jamais Tron.\n\nRésultat : vos USDT partent dans le vide. Le réseau Tron ne peut pas les envoyer vers une adresse qu''il ne reconnaît pas.\n\n**Erreur 2 : USDT-ERC20 envoyé à une adresse BNB Chain (0x…)**\n\nCelle-là est vicieuse : les adresses ERC20 et BEP20 ont le même format (0x…). Physiquement, elles peuvent même être identiques. MAIS les tokens sont émis sur des réseaux différents.\n\nCe qui se passe : les USDT partent sur Ethereum, arrivent à l''adresse, mais la personne qui contrôle cette adresse sur BNB Chain ne les voit PAS dans son wallet — parce qu''ils sont sur un autre réseau.\n\n**Récupération possible ?** Dans ce cas précis, oui, en théorie. Si le destinataire a la clé privée de cette adresse ET importe son wallet sur MetaMask configuré pour Ethereum, il peut voir et récupérer les fonds. Mais c''est technique, et beaucoup d''utilisateurs n''y parviennent pas.\n\n**Erreur 3 : USDT envoyé à une adresse Solana ou Aptos par erreur**\n\nAucune récupération possible. Les formats sont si différents que le wallet aurait dû refuser, mais certaines interfaces mal codées laissent passer.\n\n**Les 3 vérifications systématiques avant CHAQUE envoi**\n\n1. **Le réseau du wallet source** = le réseau attendu par le destinataire.\n\n2. **Le premier caractère de l''adresse** correspond au réseau :\n   • T… → Tron\n   • 0x… → Ethereum, BNB Chain ou Polygon (attention : trois possibilités !)\n   • Base58 (chiffres et lettres mélangés) → Solana\n\n3. **Le montant** est celui que vous vouliez envoyer.\n\n**Bonnes pratiques Terex**\n\nSur Terex, notre interface vous demande de choisir le réseau **avant** l''adresse. Une fois le réseau choisi, la validation d''adresse est stricte : si vous collez une adresse d''un autre réseau, un message rouge apparaît immédiatement.\n\nMais faites toujours un test avec un petit montant pour votre première transaction vers un nouveau destinataire.\n\n**En cas de doute**\n\nContactez notre support avant d''envoyer. Nous préférons répondre à 100 questions préventives plutôt qu''à une seule après une erreur irréversible.',
      6, 3
    )
  ) AS t(title, body, duration, pos)
  RETURNING 1
),
-- Module 9 — Sécurité
m9 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Sécurité : arnaques, phishing, bonnes pratiques', 9 FROM new_course
  RETURNING id
),
m9l AS (
  INSERT INTO public.lessons (module_id, title, content_type, content_text, duration_min, position)
  SELECT id, t.title, 'text', t.body, t.duration, t.pos FROM m9, (VALUES
    (
      'Les 10 arnaques crypto les plus courantes',
      E'La crypto est un environnement libre — libre aussi pour les arnaqueurs. Chaque année, des milliards de dollars sont volés à des utilisateurs pas assez vigilants. Voici les schémas les plus fréquents. Connaître = éviter.\n\n**1. Le faux support technique**\n\nQuelqu''un vous contacte sur Telegram, WhatsApp ou Discord en se présentant comme « support Trust Wallet », « support Binance », « support Terex ». Il vous demande votre phrase secrète pour « débloquer votre compte ». **AUCUN vrai support ne fait ça. JAMAIS.**\n\n**2. Le faux investissement à rendement garanti**\n\n« Investissez 100 000 CFA, doublez en 30 jours, garanti ! ». Aucun investissement légitime ne garantit un rendement, encore moins de tels chiffres. C''est un schéma pyramidal (Ponzi). Fuyez.\n\n**3. Le faux romance / amour sur Tinder ou Facebook**\n\nQuelqu''un vous drague en ligne, gagne votre confiance sur plusieurs semaines, puis vous convainc d''investir sur une « plateforme géniale ». Vous perdez tout. Ce schéma s''appelle « pig butchering » et rapporte des milliards par an.\n\n**4. Le faux airdrop / cadeau Elon Musk**\n\nUne vidéo YouTube en direct (souvent piratée) montre Elon Musk qui promet de doubler les bitcoins envoyés à une adresse. Vous envoyez, vous ne recevez rien. Elon n''organise pas d''airdrops sur YouTube.\n\n**5. Le phishing par SMS ou e-mail**\n\nVous recevez un message « Votre compte Binance a été piraté, cliquez ici pour le sécuriser ». Le lien mène à une fausse copie du site. Vous entrez vos identifiants, l''attaquant les récupère.\n\n**6. Le site copié**\n\nVous cherchez « Trust Wallet » sur Google. Le premier résultat est une pub — un faux site qui ressemble en tout point à l''original. Vous téléchargez, vous entrez votre phrase, tout est volé.\n\n**7. Le bot Telegram « d''échange »**\n\nDes groupes Telegram promettent d''échanger vos CFA contre des USDT à un taux imbattable, via un bot. Vous envoyez le paiement, jamais de USDT, bot supprimé.\n\n**8. Le faux job / recruteur**\n\nQuelqu''un vous propose un emploi « tester des applications crypto ». On vous demande de déposer une caution pour « garantir votre sérieux ». Ne payez jamais pour un emploi.\n\n**9. L''URL malveillante dans un tweet**\n\nUn projet crypto que vous suivez annonce un événement. Vous cliquez sur le lien dans un tweet — mais ce tweet est un faux, l''URL mène à un site de phishing.\n\n**10. Le « rugpull » (arnaque en projet)**\n\nUn nouveau projet crypto lance un token, fait la pub, monte artificiellement le prix, puis les créateurs vendent tout d''un coup et disparaissent. Les investisseurs se retrouvent avec des tokens sans valeur. Fréquent avec les nouvelles cryptos aux noms rigolos.\n\n**La règle universelle**\n\nEn crypto, personne ne donne rien. Aucun cadeau, aucun rendement garanti, aucun ami « super serviable » d''Internet. Si c''est trop beau pour être vrai, ça l''est.',
      7, 1
    ),
    (
      'Reconnaître un site frauduleux',
      E'Les faux sites de crypto sont l''un des vecteurs d''arnaque les plus courants. Voici comment les repérer avant de vous faire piéger.\n\n**1. Vérifier l''URL — TOUJOURS**\n\nRegardez la barre d''adresse de votre navigateur. Comparez lettre par lettre avec l''URL officielle :\n\n• `trustwallet.com` (vrai) vs `trust-wallet.com` (faux)\n• `binance.com` (vrai) vs `binance.co` (faux)\n• `terex-app.com` (vrai) vs `terex.app.security-verify.com` (faux, c''est un sous-domaine de security-verify.com)\n\nAstuce : bookmarkez les vrais sites que vous utilisez régulièrement. Utilisez toujours vos favoris plutôt que Google ou WhatsApp pour les ouvrir.\n\n**2. Ne cliquez JAMAIS sur les publicités crypto**\n\nGoogle laisse encore passer des pubs pour de faux sites crypto. Le premier résultat quand vous cherchez « Trust Wallet » est parfois une pub malveillante. Utilisez les résultats organiques ou tapez directement l''URL.\n\n**3. Vérifiez le cadenas HTTPS**\n\nTous les vrais sites crypto sont en HTTPS (petit cadenas dans la barre d''adresse). Un site sans HTTPS = suspect. MAIS attention : un cadenas ne prouve pas la légitimité, seulement le chiffrement. Un faux site peut aussi avoir un HTTPS.\n\n**4. Méfiez-vous du sentiment d''urgence**\n\n« Dernière chance ! », « Votre compte sera bloqué dans 10 minutes ! », « Airdrop expire dans 1h ! ». L''urgence est la technique préférée des arnaqueurs — elle vous empêche de réfléchir. Prenez toujours 5 minutes pour respirer et vérifier.\n\n**5. Vérifiez les avis en dehors du site**\n\n• Cherchez sur Google : « nom du site + scam » ou « nom du site + avis ».\n• Consultez Reddit (r/CryptoScams).\n• Demandez sur un groupe crypto de confiance (le nôtre par exemple, sur WhatsApp).\n\n**6. Aucun site légitime ne demande votre phrase secrète**\n\nRépétons-le : SI un site (même s''il ressemble à Trust Wallet ou MetaMask) vous demande votre phrase secrète pour « valider votre wallet », « débloquer un airdrop », « recevoir un cadeau », « migrer votre wallet »... c''est une arnaque à 100%.\n\n**7. Faites attention aux extensions de navigateur**\n\nCertaines extensions Chrome se font passer pour MetaMask ou Trust Wallet et volent votre phrase quand vous la saisissez. Ne téléchargez que depuis les liens officiels des sites concernés.\n\n**8. La règle des « 5 clics »**\n\nAvant toute action importante (connexion wallet, signature, envoi), demandez-vous : « Suis-je sur le bon site ? Est-ce que je peux le vérifier de 5 façons différentes ? »\n\n**9. Testez votre vigilance**\n\nRegardez régulièrement des vidéos de démonstration d''arnaques (chaîne « Coffeezilla » sur YouTube par exemple). Votre cerveau apprend à reconnaître les patterns.',
      6, 2
    ),
    (
      'Protéger vos comptes : 2FA, hardware wallet',
      E'Vos cryptos ne valent que ce que vaut leur protection. Voici les défenses essentielles à mettre en place.\n\n**1. Un mot de passe unique et long pour chaque plateforme**\n\nNe jamais réutiliser un mot de passe. Utilisez un gestionnaire de mots de passe (Bitwarden gratuit, 1Password payant) qui génère des mots de passe uniques de 20+ caractères.\n\nPour Terex, Binance, votre boîte mail — un mot de passe différent à chaque fois. Un piratage sur un site ne compromet pas les autres.\n\n**2. Activer la 2FA (authentification à deux facteurs) partout**\n\nLa 2FA ajoute un code à 6 chiffres généré toutes les 30 secondes, en plus de votre mot de passe. Même si un attaquant a votre mot de passe, il ne peut pas se connecter sans votre téléphone.\n\nComment activer :\n\n• Téléchargez **Google Authenticator** ou **Authy** sur votre téléphone.\n• Sur chaque site (Terex, Binance, votre e-mail Gmail), cherchez « Two-Factor Authentication » dans les paramètres de sécurité.\n• Scannez le QR code avec votre app.\n• Notez le code de récupération dans un endroit sûr.\n\n**Attention** : évitez la 2FA par SMS. Le « SIM swap » (voler votre numéro de téléphone) est trop facile. Utilisez toujours une app d''authentification.\n\n**3. Sécuriser votre boîte mail**\n\nVotre e-mail est la clé de vos comptes. Si un attaquant y accède, il peut demander des réinitialisations de mot de passe partout.\n\n• Utilisez un mot de passe très fort et unique.\n• Activez la 2FA (via app d''authentification).\n• N''utilisez cette adresse QUE pour les services financiers. Pour les inscriptions à des newsletters, créez une adresse séparée.\n\n**4. Le hardware wallet pour les gros montants**\n\nUn hardware wallet est un petit appareil (Ledger, Trezor) qui stocke vos clés privées HORS LIGNE. Même si votre ordinateur est piraté, vos clés ne quittent jamais l''appareil physique.\n\nPour tout montant au-dessus de 5000-10 000$, c''est un investissement obligatoire. Un Ledger Nano S+ coûte environ 70€ — dérisoire par rapport à ce qu''il protège.\n\n**Bonnes pratiques d''achat** : n''achetez QUE sur le site officiel (`ledger.com`, `trezor.io`). Jamais sur Amazon, jamais d''occasion — un hardware wallet compromis avant l''achat = piégé.\n\n**5. Séparer les wallets par usage**\n\n• Un wallet « chaud » (Trust Wallet, MetaMask) sur mobile pour les petits montants du quotidien.\n• Un wallet « froid » (Ledger) pour l''épargne long terme.\n• Ne jamais faire de transactions DeFi risquées depuis le wallet froid.\n\n**6. Les mises à jour**\n\nMaintenez votre téléphone, votre navigateur, votre wallet à jour. Les failles de sécurité sont patchées régulièrement — ne pas mettre à jour = laisser la porte ouverte.\n\n**7. Le VPN pour les connexions publiques**\n\nÉvitez de vous connecter à vos comptes crypto sur du Wi-Fi public (café, aéroport). Si vous devez le faire, utilisez un VPN (NordVPN, Mullvad).\n\n**En résumé**\n\nMot de passe unique + 2FA (par app) + hardware wallet pour les gros montants. Ces trois défenses éliminent 99% des attaques.',
      7, 3
    )
  ) AS t(title, body, duration, pos)
  RETURNING 1
),
-- Module 10 — Aller plus loin + Zoom
m10 AS (
  INSERT INTO public.course_modules (course_id, title, position)
  SELECT id, 'Aller plus loin & sessions en direct', 10 FROM new_course
  RETURNING id
)
INSERT INTO public.lessons (module_id, title, content_type, content_text, content_url, duration_min, position)
SELECT m10.id, t.title, t.ctype, t.body, t.url, t.duration, t.pos FROM m10, (VALUES
  (
    'DeFi — la finance décentralisée en 5 minutes',
    'text',
    E'La DeFi (Decentralized Finance) est l''écosystème des services financiers construits sur la blockchain, sans banque, sans intermédiaire.\n\n**Ce qu''on peut faire**\n\n• **Épargner** : prêter ses stablecoins pour toucher des intérêts (5 à 10% par an).\n• **Emprunter** : mettre en garantie ses cryptos pour emprunter des stablecoins, sans passer par une banque.\n• **Échanger** : swapper ses cryptos sans compte, sans KYC, en quelques clics.\n• **Fournir de la liquidité** : contribuer à un pool d''échange et toucher une part des frais.\n\n**Les protocoles majeurs**\n\n• **Aave, Compound** (Ethereum) : le prêt/emprunt de référence.\n• **Uniswap, PancakeSwap** : les échanges décentralisés (DEX).\n• **Curve, Balancer** : les DEX spécialisés stablecoins.\n• **Lido** : le staking d''ETH.\n\n**Les risques**\n\n• **Smart contract exploité** : une faille dans le code = fonds vidés.\n• **Perte impermanente** : si vous fournissez de la liquidité, vous pouvez ressortir avec moins de valeur qu''en entrant.\n• **Complexité** : une mauvaise manip et vos fonds sont perdus.\n\n**Notre conseil**\n\nCommencez par du prêt de stablecoins sur Aave (le protocole le plus audité). Testez avec 100$. Comprenez le mécanisme avant d''y mettre plus.',
    NULL, 5, 1
  ),
  (
    'Staking — faire travailler ses cryptos',
    'text',
    E'Le staking consiste à « verrouiller » ses cryptos dans un réseau blockchain pour contribuer à sa sécurité, en échange d''une récompense.\n\n**Le principe**\n\nSur les blockchains de type « Proof of Stake » (Ethereum, Solana, Cardano, Polkadot…), les validateurs qui produisent les blocs doivent immobiliser une certaine quantité de la crypto native. Plus ils immobilisent, plus ils ont de chances de valider un bloc et de toucher les récompenses.\n\nMême sans être validateur, vous pouvez « déléguer » vos cryptos à un validateur et toucher une part de ses récompenses.\n\n**Rendements typiques**\n\n• **Ethereum (ETH)** : 3-4% par an.\n• **Solana (SOL)** : 6-7% par an.\n• **Polkadot (DOT)** : 10-14% par an.\n• **Cardano (ADA)** : 3-4% par an.\n\n**Comment staker facilement**\n\n• Sur Binance ou Coinbase : « Earn » ou « Staking ». Un clic, votre crypto est stakée, vous voyez vos récompenses arriver chaque jour.\n\n• Sur Trust Wallet / MetaMask : recherchez « Stake » dans le token concerné. Vous êtes redirigé vers un validateur ou une plateforme de staking.\n\n• Directement via un protocole comme **Lido** (pour l''ETH) : plus décentralisé.\n\n**Les risques**\n\n• **Période de déblocage** : quand vous voulez récupérer vos cryptos, il peut y avoir 7-28 jours d''attente selon la blockchain.\n\n• **Slashing** : si le validateur mal agit, une partie des cryptos peut être détruite (rare mais possible).\n\n• **Volatilité** : votre crypto continue de bouger en prix. Gagner 5% en ETH ne compense pas une chute de 30% du prix d''ETH.\n\n**Staking d''USDT ?**\n\nCe n''est pas du vrai « staking » (l''USDT ne sécurise aucun réseau), mais on peut prêter ses USDT sur Aave ou Binance Earn pour toucher 5-10% par an. Idéal pour épargner sans exposition au risque de prix.',
    NULL, 5, 2
  ),
  (
    'NFT — au-delà des images',
    'text',
    E'Les NFT (Non-Fungible Tokens) sont des jetons uniques inscrits sur la blockchain. Ils ont fait la une des médias en 2021-2022 avec des images de singes vendues des millions. Mais leur usage réel va bien au-delà.\n\n**Le concept**\n\nUn NFT est comme un certificat d''authenticité numérique. Contrairement à un USDT ou un BTC (où toutes les unités sont identiques et interchangeables), chaque NFT est unique et prouve la propriété d''un actif spécifique.\n\n**Les usages sérieux qui émergent**\n\n• **Billets d''événements** : Ticketmaster teste les NFT pour éliminer la revente illégale.\n\n• **Diplômes et certifications** : universités qui délivrent des diplômes sous forme de NFT infalsifiables.\n\n• **Actes de propriété** : des projets pilotes au Ghana, en Géorgie, en Suède pour numériser les titres fonciers.\n\n• **Objets in-game** : dans les jeux vidéo, vous possédez vraiment votre épée, votre skin, votre personnage — et pouvez les revendre.\n\n• **Musique et royalties** : les artistes vendent leur musique directement à leur audience sans passer par les plateformes.\n\n• **Adhésions et clubs** : certains restaurants, clubs de sport, communautés fonctionnent avec un NFT comme « carte de membre ».\n\n**Ce qu''on peut y perdre**\n\nLe marché de l''art NFT est très spéculatif. Beaucoup de collections ont perdu 90%+ de leur valeur. Achetez un NFT parce que vous en aimez l''objet ou l''usage — pas pour spéculer.\n\n**Les grandes plateformes**\n\n• **OpenSea, Blur** : sur Ethereum et Polygon.\n• **Magic Eden** : sur Solana.\n• **Rarible** : multi-chaînes.\n\n**Notre conseil**\n\nSi les NFT vous intriguent, commencez par en acheter un à petit prix (10$) sur Polygon (frais très bas). Comprenez comment les stocker dans votre wallet, comment les envoyer, comment les revendre. C''est un excellent exercice pour maîtriser les concepts crypto.',
    NULL, 5, 3
  ),
  (
    'Session Zoom mensuelle — Questions/Réponses avec l''équipe Terex',
    'zoom',
    E'Chaque premier samedi du mois, à 17h (heure de Dakar), l''équipe Terex organise une session Zoom en direct pour les élèves de l''Academy.\n\nAu programme :\n\n• **Réponses à vos questions** — envoyez-nous vos questions par avance ou posez-les en direct.\n• **Actualité crypto du mois** — les évolutions à surveiller, les opportunités, les alertes.\n• **Étude de cas** — nous analysons ensemble une transaction réelle, un projet, une situation.\n• **Retours d''expérience** — vous partagez votre parcours, vos erreurs, vos réussites.\n\nLe lien Zoom vous est envoyé par e-mail et affiché ici 24h avant la session.\n\n**Comment participer**\n\n1. Installez Zoom sur votre téléphone ou votre ordinateur si ce n''est pas déjà fait.\n2. À l''heure de la session, cliquez sur le bouton « Rejoindre » ci-dessous.\n3. Activez votre micro pour poser une question ou utilisez le chat.\n\n**Enregistrement**\n\nChaque session est enregistrée. Le replay est mis à disposition ici 48h après la session pour ceux qui n''ont pas pu se joindre en direct.\n\n**Notre engagement**\n\nCes sessions sont gratuites, sans upsell, sans pitch commercial. C''est un espace d''apprentissage et de communauté. Notre seul objectif : faire de vous un utilisateur crypto éclairé et autonome.\n\nÀ très bientôt en direct.',
    'https://us02web.zoom.us/j/00000000000',
    60, 4
  )
) AS t(title, ctype, body, url, duration, pos);
